describe('In-app Notifications Real-time Updates', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser@example.com', 'password123');
    cy.wait(1000);
  });

  it('should display new notifications in real-time without page refresh', () => {
    // Navigate to notifications area
    cy.get('[data-testid="notifications-icon"]').click();
    cy.get('[data-testid="notifications-panel"]').should('be.visible');

    // Get initial notification count
    cy.get('[data-testid="notification-count"]').then(($count) => {
      const initialCount = parseInt($count.text());

      // Simulate receiving a new notification via WebSocket/API
      cy.window().then((win) => {
        win.dispatchEvent(new CustomEvent('notification:new', {
          detail: {
            id: 'notif-' + Date.now(),
            message: 'Test notification',
            type: 'info',
            timestamp: new Date().toISOString()
          }
        }));
      });

      // Verify notification appears without refresh
      cy.get('[data-testid="notification-item"]').should('have.length', initialCount + 1);
      cy.get('[data-testid="notification-item"]').first().should('contain', 'Test notification');
      cy.get('[data-testid="notification-count"]').should('contain', initialCount + 1);
    });
  });

  it('should handle multiple rapid notifications without losing any', () => {
    cy.get('[data-testid="notifications-icon"]').click();
    cy.get('[data-testid="notifications-panel"]').should('be.visible');

    // Get initial count
    cy.get('[data-testid="notification-count"]').then(($count) => {
      const initialCount = parseInt($count.text());

      // Send multiple notifications rapidly
      cy.window().then((win) => {
        for (let i = 0; i < 5; i++) {
          win.dispatchEvent(new CustomEvent('notification:new', {
            detail: {
              id: 'notif-rapid-' + i,
              message: `Rapid notification ${i + 1}`,
              type: 'success',
              timestamp: new Date().toISOString()
            }
          }));
        }
      });

      // Verify all notifications appear
      cy.get('[data-testid="notification-item"]').should('have.length', initialCount + 5);
      cy.get('[data-testid="notification-count"]').should('contain', initialCount + 5);

      // Verify each notification is present
      for (let i = 0; i < 5; i++) {
        cy.get('[data-testid="notification-item"]').should('contain', `Rapid notification ${i + 1}`);
      }
    });
  });

  it('should update notification status in real-time when marked as read', () => {
    cy.get('[data-testid="notifications-icon"]').click();
    cy.get('[data-testid="notifications-panel"]').should('be.visible');

    // Get first unread notification
    cy.get('[data-testid="notification-item"][data-read="false"]').first().as('unreadNotif');

    // Verify it's unread
    cy.get('@unreadNotif').should('have.attr', 'data-read', 'false');
    cy.get('@unreadNotif').should('have.class', 'unread');

    // Click to mark as read
    cy.get('@unreadNotif').click();

    // Verify status updates without refresh
    cy.get('@unreadNotif').should('have.attr', 'data-read', 'true');
    cy.get('@unreadNotif').should('not.have.class', 'unread');
    cy.get('@unreadNotif').should('have.class', 'read');
  });

  it('should remove dismissed notifications in real-time', () => {
    cy.get('[data-testid="notifications-icon"]').click();
    cy.get('[data-testid="notifications-panel"]').should('be.visible');

    // Get initial notification count
    cy.get('[data-testid="notification-item"]').then(($items) => {
      const initialCount = $items.length;

      // Get first notification and dismiss it
      cy.get('[data-testid="notification-item"]').first().as('firstNotif');
      cy.get('@firstNotif').find('[data-testid="dismiss-btn"]').click();

      // Verify notification is removed without refresh
      cy.get('[data-testid="notification-item"]').should('have.length', initialCount - 1);
      cy.get('@firstNotif').should('not.exist');
    });
  });

  it('should handle notification with different types and display appropriate styling', () => {
    cy.get('[data-testid="notifications-icon"]').click();
    cy.get('[data-testid="notifications-panel"]').should('be.visible');

    const notificationTypes = ['info', 'success', 'warning', 'error'];

    cy.window().then((win) => {
      notificationTypes.forEach((type, index) => {
        win.dispatchEvent(new CustomEvent('notification:new', {
          detail: {
            id: 'notif-type-' + type,
            message: `${type.charAt(0).toUpperCase() + type.slice(1)} notification`,
            type: type,
            timestamp: new Date().toISOString()
          }
        }));
      });
    });

    // Verify each notification type has correct styling
    notificationTypes.forEach((type) => {
      cy.get(`[data-testid="notification-item"][data-type="${type}"]`)
        .should('exist')
        .should('have.class', `notification-${type}`);
    });
  });
});
